-- Demo library: a fictional reader for local-mode screenshots and design review.
--
-- 19 books with Open Library covers, enrichment rows, and hand-authored taste
-- traits and archetype (not Claude-generated), all under user_id 'local'. No
-- real account data, no emails, no API keys. Load it into an empty database
-- that is already migrated to the checked-in schema:
--
--   DATABASE_URL=postgresql://... npm run db:migrate
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f scripts/demo-library.sql
--
-- Then run the app in local mode (ALLOW_LOCAL_AUTH=true, no Supabase vars, no
-- .env in scope). Regenerate with pg_dump --data-only --column-inserts from a
-- database holding the demo library, excluding invite_requests, rate_limits
-- and the drizzle schema.
--
-- PostgreSQL database dump
--


-- Dumped from database version 16.15
-- Dumped by pg_dump version 16.15

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;

