=gbs_api", "accessViewStatus": "NONE", "quoteSharingAllowed": false, "textToSpeechPermission": "ALLOWED"}, "searchInfo": {"textSnippet": "This is a reproduction of the original artefact. Generally these books are created from careful scans of the original. This allows us to preserve the book accurately and present it in the way the author intended."}, "volumeInfo": {"title": "The Old Man of the Mountain", "infoLink": "http://books.google.co.uk/books?id=pKMCzAEACAAJ&dq=intitle:%22Old+Man%27s+War+Scalzi%22&hl=&source=gbs_api", "language": "en", "subtitle": "The Love Charm; and Pietro of Abano", "pageCount": 224, "printType": "BOOK", "categories": ["History"], "imageLinks": {"thumbnail": "http://books.google.com/books/content?id=pKMCzAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api", "smallThumbnail": "http://books.google.com/books/content?id=pKMCzAEACAAJ&printsec=frontcover&img=1&zoom=5&source=gbs_api"}, "previewLink": "http://books.google.co.uk/books?id=pKMCzAEACAAJ&dq=intitle:%22Old+Man%27s+War+Scalzi%22&hl=&cd=3&source=gbs_api", "readingModes": {"text": false, "image": false}, "publishedDate": "2019-10-26", "contentVersion": "preview-1.0.0", "maturityRating": "NOT_MATURE", "allowAnonLogging": false, "canonicalVolumeLink": "https://books.google.com/books/about/The_Old_Man_of_the_Mountain.html?hl=&id=pKMCzAEACAAJ", "industryIdentifiers": [{"type": "ISBN_10", "identifier": "0461403676"}, {"type": "ISBN_13", "identifier": "9780461403671"}], "panelizationSummary": {"containsEpubBubbles": false, "containsImageBubbles": false}}}], "totalItems": 3}', '2026-09-08 20:02:50.574545');
