INSERT INTO public.catalog_cache (cache_key, source, payload, fetched_at) VALUES ('ce399f78aa1720488a326b8d232b81922896fd17', 'openlibrary', '{"key": "/works/OL21680947W", "type": {"key": "/type/work"}, "links": [{"url": "https://www.athenaeum.nl/leesfragmenten/2023/het-ministerie-voor-de-toekomst", "type": {"key": "/type/link"}, "title": "leesfragment"}, {"url": "https://alxd.org/ministry-for-the-future-review.html", "type": {"key": "/type/link"}, "title": "Review by Pawel Ngei"}], "title": "The Ministry for the Future", "covers": [10477770, 13865149], "authors": [{"type": {"key": "/type/author_role"}, "author": {"key": "/authors/OL19986A"}}, {"type": {"key": "/type/author_role"}, "author": {"key": "/authors/OL9160602A"}}], "created": {"type": "/type/datetime", "value": "2020-08-26T10:00:33.212392"}, "revision": 15, "subjects": ["American literature", "Fiction", "Environmental policy", "Officials and employees", "Climatic changes", "Humanitarian aid workers", "Post-traumatic stress disorder", "Political kidnapping", "Terrorist organizations", "The Future", "Employees", "United Nations", "Climate", "Climate change", "Global Warming & Climate Change"], "description": "*The Ministry for the Future* is a masterpiece of the imagination, using fictional eyewitness accounts to tell the story of how climate change will affect us all. Its setting is not a desolate, post-apocalyptic world, but a future that is almost upon us. Chosen by Barack Obama as one of his favorite books of the year, this extraordinary novel from visionary science fiction writer Kim Stanley Robinson will change the way you think about the climate crisis.\r\n\r\nONE OF BARACK OBAMA’S FAVORITE BOOKS OF THE YEAR\r\n\r\n“The best science-fiction nonfiction novel I’ve ever read.” —Jonathan Lethem\r\n \r\n\"If I could get policymakers, and citizens, everywhere to read just one book this year, it would be Kim Stanley Robinson’s The Ministry for the Future.\" —Ezra Klein (Vox)\r\n\r\n\"One hopes that this book is read widely—that Robinson’s audience, already large, grows by an order of magnitude. Because the point of his books is to fire the imagination.\"―New York Review of Books\r\n\r\n\"If there’s any book that hit me hard this year, it was Kim Stanley Robinson’s The Ministry for the Future, a sweeping epic about climate change and humanity’s efforts to try and turn the tide before it’s too late.\" ―Polygon (Best of the Year)\r\n \r\n\"Masterly.\" —New Yorker\r\n\r\n\"[The Ministry for the Future] struck like a mallet hitting a gong, reverberating through the year ... it’s terrifying, unrelenting, but ultimately hopeful. Robinson is the SF writer of my lifetime, and this stands as some of his best work. It’s my book of the year.\" —Locus\r\n\r\n\"Science-fiction visionary Kim Stanley Robinson makes the case for quantitative easing our way out of planetary doom.\" ―Bloomberg Green\r\n\r\nSource: Publisher", "last_modified": {"type": "/type/datetime", "value": "2025-09-27T16:19:58.263299"}, "subject_people": ["Frank May", "Mary Murphy"], "subject_places": ["Zurich", "India"], "latest_revision": 15}', '2026-09-08 20:23:57.195472');


