INSERT INTO public.reader_archetypes (id, user_id, code, archetype_name, archetype_tagline, axis_lens, axis_engine, axis_range, axis_resonance, lens_rationale, engine_rationale, range_rationale, resonance_rationale, derived_at) VALUES (1, 'local', 'RCDM', 'The Cerebral Architect', 'A well-constructed mind on the page -- that''s everything.', 0.62, 0.55, 0.48, 0.71, 'Your highest ratings go to books where the sentence is doing as much work as the plot.', 'Interiority outranks incident across every tier of your ratings.', 'You go deep on a handful of authors rather than wide across the shelf.', 'You rate for what a book means, not for how efficiently it moves.', '2026-08-24 19:06:29.395604');


