INSERT INTO public.taste_traits (id, user_id, claim, polarity, exhibits, contrasts, inference_confidence, status, user_note, created_at, user_weight, verdict_updated_at, reveal_line, exhibit_title_ids, contrast_title_ids) VALUES (6, 'local', 'You are drawn to narrators who do not understand their own situation, and you rate highest when the gap between what the narrator knows and what you know is the engine of the book.', 'reward', '"[20,22,24]"', '"[35]"', 0.91, 'proposed', NULL, '2026-08-24 19:08:53.786149', 1, NULL, 'You love an unreliable narrator who is not lying.', NULL, NULL);
INSERT INTO public.taste_traits (id, user_id, claim, polarity, exhibits, contrasts, inference_confidence, status, user_note, created_at, user_weight, verdict_updated_at, reveal_line, exhibit_title_ids, contrast_title_ids) VALUES (7, 'local', 'Invented social systems land for you only when the book treats them as arguments rather than scenery. Worldbuilding as set dressing consistently drops a full star.', 'reward', '"[21,25,30]"', '"[34]"', 0.84, 'proposed', NULL, '2026-08-24 19:08:53.788036', 1, NULL, 'You want the world to be making a point.', NULL, NULL);
INSERT INTO public.taste_traits (id, user_id, claim, polarity, exhibits, contrasts, inference_confidence, status, user_note, created_at, user_weight, verdict_updated_at, reveal_line, exhibit_title_ids, contrast_title_ids) VALUES (8, 'local', 'You reward restraint in prose. The books you rate 4.5 and up withhold; the ones you rate below 3 explain.', 'reward', '"[22,27,20]"', '"[34,35]"', 0.78, 'proposed', NULL, '2026-08-24 19:08:53.789464', 1, NULL, 'Withholding beats explaining, every time.', NULL, NULL);
INSERT INTO public.taste_traits (id, user_id, claim, polarity, exhibits, contrasts, inference_confidence, status, user_note, created_at, user_weight, verdict_updated_at, reveal_line, exhibit_title_ids, contrast_title_ids) VALUES (9, 'local', 'Nostalgia and reference as a substitute for substance is your most reliable aversion. It is the one thing that pulls a rating below 2.5 regardless of genre.', 'aversion', '"[34,35]"', '"[26]"', 0.88, 'proposed', NULL, '2026-08-24 19:08:53.790877', 1, NULL, 'Recognition is not a feeling you rate highly.', NULL, NULL);
INSERT INTO public.taste_traits (id, user_id, claim, polarity, exhibits, contrasts, inference_confidence, status, user_note, created_at, user_weight, verdict_updated_at, reveal_line, exhibit_title_ids, contrast_title_ids) VALUES (10, 'local', 'You return to a small number of authors and read them nearly completely, rather than sampling widely across a genre.', 'reward', '"[23,29,32]"', '"[]"', 0.72, 'proposed', NULL, '2026-08-24 19:08:53.792527', 1, NULL, 'You read authors, not genres.', NULL, NULL);


